diff:
diff --git a/debian/changelog b/debian/changelog
index c4ce75e..83b5e98 100644
--- a/debian/changelog
+++ b/debian/changelog
@@ -1,3 +1,9 @@
+cyrus-sasl2 (2.1.27+dfsg2-3ubuntu1.3) jammy; urgency=medium
+
+  * d/p/honor-log-level: Allow users to set log level (LP: #827151)
+
+ -- Luciano Lo Giudice <luciano.logiudice@canonical.com>  Thu, 24 Jul 2025 16:19:18 -0300
+
 cyrus-sasl2 (2.1.27+dfsg2-3ubuntu1.2) jammy; urgency=medium

   * d/control, d/libsasl2-modules-gssapi-mit.install,
diff --git a/debian/patches/honor-log-level.patch b/debian/patches/honor-log-level.patch
new file mode 100644
index 0000000..7246692
--- /dev/null
+++ b/debian/patches/honor-log-level.patch
@@ -0,0 +1,70 @@
+Origin: upstream, https://github.com/cyrusimap/cyrus-sasl/commit/cb549ef71c5bb646fe583697ebdcaba93267a237
+Bug: https://github.com/cyrusimap/cyrus-sasl/issues/386
+Bug-Ubuntu: https://bugs.launchpad.net/ubuntu/jammy/+source/cyrus-sasl2/+bug/827151
+Last-Update: 2022-05-25
+Description: honor log_level option on clients too
+Signed-off-by: Howard Chu <hyc@symas.com>
+Forwarded: no
+
+diff --git a/include/saslplug.h b/include/saslplug.h
+index ab79e68..988010f 100755
+--- a/include/saslplug.h
++++ b/include/saslplug.h
+@@ -305,7 +305,7 @@ typedef struct sasl_client_params {
+     int (*spare_fptr1)(void);
+ 
+     unsigned int cbindingdisp;
+-    int spare_int2;
++    int log_level;
+     int spare_int3;
+ 
+     /* flags field as passed to sasl_client_new */
+diff --git a/lib/client.c b/lib/client.c
+index 04ad7d5..a00746d 100644
+--- a/lib/client.c
++++ b/lib/client.c
+@@ -400,7 +400,7 @@ int sasl_client_new(const char *service,
+   sasl_utils_t *utils;
+   sasl_getopt_t *getopt;
+   void *context;
+-  const char *mlist = NULL;
++  const char *mlist = NULL, *log_level = NULL;
+   int plus = 0;
+ 
+   if (_sasl_client_active == 0) return SASL_NOTINIT;
+@@ -443,9 +443,12 @@ int sasl_client_new(const char *service,
+   conn->cparams->utils = utils;
+ 
+   if(_sasl_getcallback(*pconn, SASL_CB_GETOPT, (sasl_callback_ft *)&getopt, &context) == SASL_OK) {
++    getopt(context, NULL, "log_level", &log_level, NULL);
+     getopt(context, NULL, "client_mech_list", &mlist, NULL);
+   }
+ 
++  conn->cparams->log_level = log_level ? atoi(log_level) : SASL_LOG_ERR;
++
+   /* if we have a client_mech_list, create ordered list of
+      available mechanisms for this conn */
+   if (mlist) {
+diff --git a/lib/common.c b/lib/common.c
+index bc3bf1d..b2bf94a 100644
+--- a/lib/common.c
++++ b/lib/common.c
+@@ -1480,13 +1480,16 @@ static int _sasl_syslog(void *context,
+ 			const char *message)
+ {
+     int syslog_priority;
+-    sasl_server_conn_t *sconn;
+ 
+     if (context) {
+ 	if (((sasl_conn_t *)context)->type == SASL_CONN_SERVER) {
+-	    sconn = (sasl_server_conn_t *)context;
++	    sasl_server_conn_t *sconn = (sasl_server_conn_t *)context;
+ 	    if (sconn->sparams->log_level < priority) 
+ 		return SASL_OK;
++	} else {
++	    sasl_client_conn_t *conn = (sasl_client_conn_t *)context;
++	    if (conn->cparams->log_level < priority)
++	        return SASL_OK;
+ 	}
+     }
+ 
diff --git a/debian/patches/series b/debian/patches/series
index d65fedd..1353ecc 100644
--- a/debian/patches/series
+++ b/debian/patches/series
@@ -30,3 +30,4 @@ CVE-2022-24407.patch
 0034-channel-binding-gssapi-gss-spnego.patch
 0035-Add-support-for-setting-max-ssf-0-to-GSS-SPNEGO-1.patch
 0035-Add-support-for-setting-max-ssf-0-to-GSS-SPNEGO-2.patch
+honor-log-level.patch
